{
  "name": "是德科技 N777x 可调谐激光模块",
  "name_en": "Keysight N777x Tunable Laser Module",
  "manufacturer": "Keysight Technologies",
  "description": "N777x 是一款用于光通信与光子学实验的可调谐激光模块，可在一定波长范围内提供稳定激光输出，并支持功率调节、步进或连续波长扫描以及触发同步，常用于光器件表征、插损测试和扫波测量。",
  "description_en": "The N777x is a tunable laser module for optical communications and photonics laboratories. It provides stable laser output over a selectable wavelength range and supports power control, stepped or continuous wavelength sweeps, and trigger synchronization for tasks such as optical component characterization, insertion-loss testing, and swept-wavelength measurements.",
  "tag_hints": [
    "tunable laser source",
    "wavelength sweep",
    "optical communications test",
    "photonics characterization",
    "laser power control",
    "trigger synchronization",
    "list-mode sweep"
  ],
  "actions": [
    {
      "action_name": "auto-update_gui_parameters",
      "description": "更新设备可配置参数选项。",
      "description_en": "Update the configurable device parameter options."
    },
    {
      "action_name": "auto-apply_gui_parameters",
      "description": "应用所选设备配置参数。",
      "description_en": "Apply the selected device configuration parameters."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化可调谐激光模块。",
      "description_en": "Initialize the tunable laser module."
    },
    {
      "action_name": "auto-deinitialize",
      "description": "结束使用并关闭初始化状态。",
      "description_en": "Deinitialize the instrument at the end of use."
    },
    {
      "action_name": "auto-configure",
      "description": "配置激光输出与扫描相关设置。",
      "description_en": "Configure the laser output and sweep-related settings."
    },
    {
      "action_name": "auto-unconfigure",
      "description": "恢复先前的触发或工作设置。",
      "description_en": "Restore the previous trigger or operating settings."
    },
    {
      "action_name": "auto-configure_list_mode",
      "description": "将激光器配置为列表模式波长扫描。",
      "description_en": "Configure the laser for wavelength sweeps in list mode."
    },
    {
      "action_name": "auto-poweron",
      "description": "开启模块以进入工作状态。",
      "description_en": "Power on the module for operation."
    },
    {
      "action_name": "auto-poweroff",
      "description": "关闭模块或退出工作状态。",
      "description_en": "Power off the module or leave the active operating state."
    },
    {
      "action_name": "auto-apply",
      "description": "应用新的激光输出设定。",
      "description_en": "Apply the new laser output settings."
    },
    {
      "action_name": "auto-measure",
      "description": "触发一次测量或扫描采集。",
      "description_en": "Trigger a measurement or sweep acquisition."
    },
    {
      "action_name": "auto-request_result",
      "description": "请求当前扫描结果。",
      "description_en": "Request the current sweep result."
    },
    {
      "action_name": "auto-wait_for_sweep_completion",
      "description": "等待波长扫描完成。",
      "description_en": "Wait for the wavelength sweep to complete."
    },
    {
      "action_name": "auto-call",
      "description": "返回当前测量结果。",
      "description_en": "Return the current measurement results."
    },
    {
      "action_name": "auto-reset",
      "description": "将仪器复位到默认状态。",
      "description_en": "Reset the instrument to its default state."
    },
    {
      "action_name": "auto-clear_status",
      "description": "清除状态与错误队列。",
      "description_en": "Clear the status and error queue."
    },
    {
      "action_name": "auto-set_power_unit",
      "description": "设置输出功率单位。",
      "description_en": "Set the output power unit."
    },
    {
      "action_name": "auto-set_power",
      "description": "设置输出功率。",
      "description_en": "Set the output power."
    },
    {
      "action_name": "auto-set_wavelength",
      "description": "设置激光波长。",
      "description_en": "Set the laser wavelength."
    },
    {
      "action_name": "auto-turn_key",
      "description": "切换激光安全钥匙状态。",
      "description_en": "Change the state of the laser safety key."
    },
    {
      "action_name": "auto-check_key_turned",
      "description": "检查激光安全钥匙是否已打开。",
      "description_en": "Check whether the laser safety key is turned."
    },
    {
      "action_name": "auto-set_laser_on",
      "description": "打开激光输出。",
      "description_en": "Turn the laser output on."
    },
    {
      "action_name": "auto-set_laser_off",
      "description": "关闭激光输出。",
      "description_en": "Turn the laser output off."
    },
    {
      "action_name": "auto-is_laser_on",
      "description": "检查激光输出是否开启。",
      "description_en": "Check whether the laser output is on."
    },
    {
      "action_name": "auto-check_errors",
      "description": "检查仪器错误状态。",
      "description_en": "Check the instrument error status."
    },
    {
      "action_name": "auto-set_trigger_configuration",
      "description": "设置触发配置。",
      "description_en": "Set the trigger configuration."
    },
    {
      "action_name": "auto-set_sweep_cycles",
      "description": "设置扫描循环次数。",
      "description_en": "Set the number of sweep cycles."
    },
    {
      "action_name": "auto-set_sweep_speed",
      "description": "设置扫描速度。",
      "description_en": "Set the sweep speed."
    },
    {
      "action_name": "auto-set_sweep_start",
      "description": "设置扫描起始波长。",
      "description_en": "Set the sweep start wavelength."
    },
    {
      "action_name": "auto-set_sweep_stop",
      "description": "设置扫描终止波长。",
      "description_en": "Set the sweep stop wavelength."
    },
    {
      "action_name": "auto-set_sweep_step",
      "description": "设置扫描步进。",
      "description_en": "Set the sweep step size."
    },
    {
      "action_name": "auto-configure_trigger_output",
      "description": "配置触发输出条件。",
      "description_en": "Configure the trigger output condition."
    }
  ]
}

